mapper.update:
UPDATE device_command_record
SET status = 'SENT', sent_at = #{sentAt,jdbcType=TIMESTAMP}
WHERE command_id = #{commandId} AND status IN ('PENDING', 'SENT')

UPDATE device_command_record
SET status = 'ACKED', result = #{result}, finished_at = #{finishedAt,jdbcType=TIMESTAMP}
WHERE command_id = #{commandId} AND status IN ('PENDING', 'SENT')

UPDATE device_command_record
SET status = 'FAILED', error_message = #{errorMessage}, finished_at = #{finishedAt,jdbcType=TIMESTAMP}
WHERE command_id = #{commandId} AND status IN ('PENDING', 'SENT')

UPDATE device_command_record
SET status = 'TIMEOUT', error_message = #{errorMessage}, finished_at = #{finishedAt,jdbcType=TIMESTAMP}
WHERE command_id = #{commandId} AND status IN ('PENDING', 'SENT')

UPDATE device_command_record
SET status = 'TIMEOUT', error_message = #{errorMessage}, finished_at = NOW(3)
WHERE status IN ('PENDING', 'SENT') AND call_type = #{callType} AND created_at < #{before,jdbcType=TIMESTAMP}
LIMIT #{limit}
